# Databricks notebook source
# MAGIC %md
# MAGIC # dept_ingest (migrated from the Elasticsearch ingest pipeline)
# MAGIC The `_bulk` + ingest pipeline becomes Auto Loader -> Bronze -> these
# MAGIC transforms -> Silver. Generated by es2dbx.

# COMMAND ----------
from pyspark.sql import functions as F

raw = (spark.readStream.format("cloudFiles")
       .option("cloudFiles.format", "json")
       .option("cloudFiles.schemaLocation", "/Volumes/bank/landing/_schema/dept")
       .load("/Volumes/bank/landing/dept")
       .withColumn("_ingested_at", F.current_timestamp()))

# COMMAND ----------
# MAGIC %md ## Ingest pipeline processors
def apply_pipeline(df):
    df = df.withColumnRenamed("DEPT_CODE", "dept")
    df = df.withColumn("dept", F.lower(F.col("dept")))
    df = df.withColumnRenamed("TXN_ID", "doc_id")
    df = df.withColumnRenamed("TXN_DATE", "txn_date")
    df = df.withColumn("txn_date", F.to_date(F.col("txn_date"), "yyyy-MM-dd"))
    df = df.withColumn("amount", F.col("AMOUNT").cast("double"))
    df = df.withColumn("STATUS", F.regexp_replace(F.col("STATUS"), r"\s+", ""))
    df = df.withColumn("ccy", F.lower(F.col("CCY")))
    df = df.withColumn("base_ccy", F.lit("CAD"))
    df = df.withColumn("base_amount", F.col("amount") * 1.0)
    df = df.withColumn("txn_kind", F.regexp_extract(F.col("NARRATIVE"), r"(?P<txn_kind>\w+)", 1))
    df = df.withColumn("tags", F.lit(F.array("bank", "dept-feed")))
    return df

# COMMAND ----------
silver = apply_pipeline(raw)
silver.writeStream.format("delta").outputMode("append") \
      .option("checkpointLocation", "/Volumes/bank/landing/_ckpt/dept") \
      .trigger(availableNow=True).toTable("bank.silver.dept_txn")
print("ingested")
